# ==================== PDF 抽取邏輯 ====================

def normalize(s):
    """去空白、Unicode 正規化(把 ⽂→文 等異體字統一)"""
    if s is None:
        return ""
    s = str(s)
    s = unicodedata.normalize('NFKC', s)
    return re.sub(r'\s+', '', s)


def is_main_data_row(row):
    """判斷是否為主表資料列"""
    if not row or len(row) < 13:
        return False
    站版 = normalize(row[0])
    if not 站版 or 站版 == "合計" or "站版" in 站版:
        return False
    try:
        int(row[4])
        return True
    except (ValueError, TypeError):
        return False


# 主軸縮寫對照(PDF 中主軸欄位常被切成單字)
# 由於不同專案可能有不同主軸類型,擴充常見對照;未列出的縮寫會用「文字解析」自動補
主軸縮寫對照 = {
    "自": "自品置入",
    "需": "需求置入",
    "圖": "圖書/閱讀",
    "會": "會員/品牌",
    "百": "百貨",
    "競": "競品置入",  # 或「競品議題置入」
    "全": "全域置入",
    "社": "社團置入",
    "消": "消費者需求置入",
    "情": "情境話題",
    "產": "產品話題",
    "話": "話題",
}

# 站版前綴關鍵字 — 用來辨識一行是否以「站版」開頭
站版前綴 = ["Threads", "PTT", "Facebook", "Dcard", "Mobile01", "eyny", "Plurk",
             "BabyHome", "FG", "伊莉", "狄卡", "批踢踢", "FashionGuide"]

# 行尾「主軸 + 日期前半 + 9 個數字」的通用特徵
# 主軸允許:任何非數字、非空白的字符組合 — 不限定中文開頭
# 涵蓋「自/需/圖」「全院-」「miradry」「ABC-123」等任何寫法
ROW_PATTERN = re.compile(
    r'([^\s\d][^\s]*)\s+'                                          # 主軸縮寫(非數字、非空白開頭)
    r'\d{4}-\s+'                                                   # 日期 yyyy-
    r'(\d+)\s+(\d+)\s+(\d+)\s+(\d+)\s+'                            # 發文 回應 聲量 正向
    r'(\d+)\s+(\d+)\s+(\d+)\s+(\d+)\s+(\d+)'                       # 正面 負面 議題 產品 複合
    r'\s*$', re.MULTILINE
)


def get_main_category_from_pdf(pdf_path):
    """從 PDF「操作主軸」區塊抽出實際主軸全名清單(用文字解析,避免跨頁切表問題)"""
    with pdfplumber.open(pdf_path) as pdf:
        full_text = ""
        for page in pdf.pages:
            full_text += unicodedata.normalize('NFKC', page.extract_text() or "") + "\n"
    
    extracted = []
    
    # 找「操作主軸」區段
    start_idx = full_text.find("操作主軸")
    if start_idx < 0:
        return extracted
    
    # 找區段結尾(碰到下個區段就停)
    end_markers = ["專案聲量分佈", "網友關注度", "網友回應概況"]
    end_idx = len(full_text)
    for marker in end_markers:
        idx = full_text.find(marker, start_idx + 10)
        if 0 < idx < end_idx:
            end_idx = idx
    
    section = full_text[start_idx:end_idx]
    
    # 匹配「主軸名 + 空白 + 純數字」
    for line in section.split('\n'):
        line = line.strip()
        if not line:
            continue
        if line in ("操作主軸", "類型 累計", "類型", "累計"):
            continue
        m = re.match(r'^(.+?)\s+(\d+)\s*$', line)
        if m:
            name = m.group(1).strip()
            if name == "合計":
                continue
            # 排除站版列、含百分比的列
            if ":" in name or "%" in name:
                continue
            if re.search(r'\d+\.\d+', line):
                continue
            extracted.append(name)
    
    return extracted


def resolve_main_category(prefix, full_names):
    """把截斷的主軸縮寫對應到完整名稱
    
    優先級:
    1. 完全相同
    2. 完整名稱開頭就是縮寫(prefix match)
    3. 無法對應 → 回傳原縮寫
    """
    if not prefix:
        return prefix
    # 1. 完全相同
    for name in full_names:
        if name == prefix:
            return name
    # 2. 開頭匹配(全名以縮寫開頭)
    for name in full_names:
        if name.startswith(prefix):
            return name
    # 3. 反向匹配(縮寫以全名開頭,例如「全院-逆時針」會出現「全院-逆」被截斷)
    for name in full_names:
        if prefix.startswith(name) and len(name) >= 2:
            return name
    return prefix


def extract_main_table_via_text(pdf_path):
    """用「行尾 9 個數字」特徵從純文字中抓主表資料(比 extract_tables 穩健)
    
    判斷邏輯:任何一行只要結尾是「中文字 + yyyy- + 9個數字」就視為資料列。
    這個結構足以唯一識別資料列(合計列、表頭、空白行都不會符合)。
    不依賴站版名稱字典,適用於任何站版。
    """
    with pdfplumber.open(pdf_path) as pdf:
        full_text = ""
        for page in pdf.pages:
            page_text = page.extract_text() or ""
            full_text += unicodedata.normalize('NFKC', page_text) + "\n"
    
    # 從 PDF「操作主軸」表抓主軸全名清單(動態,不寫死)
    full_names = get_main_category_from_pdf(pdf_path)
    
    rows = []
    for m in ROW_PATTERN.finditer(full_text):
        主軸縮寫 = m.group(1)
        nums = [int(m.group(i)) for i in range(2, 11)]
        
        # 取該行從行首到主軸縮寫之前的文字 = 站版 + 標題
        line_start = full_text.rfind('\n', 0, m.start()) + 1
        line_part = full_text[line_start:m.start()].strip()
        
        # 過濾:行內容太短就跳過(避免抓到合計列等)
        if len(line_part) < 3:
            continue
        
        # 把可能截斷的主軸縮寫對應到完整名稱
        # 優先使用 PDF「操作主軸」表的全名清單做 prefix match
        # 查不到再用內建對照表;都查不到就用原縮寫
        主軸全名 = resolve_main_category(主軸縮寫, full_names)
        if 主軸全名 == 主軸縮寫 and 主軸縮寫 in 主軸縮寫對照:
            主軸全名 = 主軸縮寫對照[主軸縮寫]
        
        rows.append({
            "站版": line_part,
            "標題": "",
            "主軸": 主軸全名,
            "專案發文量": nums[0],
            "網友回應量": nums[1],
            "討論聲量總數": nums[2],
            "正向聲量總數": nums[3],
            "正面討論": nums[4],
            "負面討論": nums[5],
            "議題討論": nums[6],
            "產品討論": nums[7],
            "複合討論": nums[8],
        })
    return rows


def extract_main_table(pdf_path):
    """主表抽取的對外接口(目前用文字解析法,最穩定)"""
    return extract_main_table_via_text(pdf_path)


def extract_posts_with_content(pdf_path):
    """從「專案發文總覽 PDF」抽出每篇文章的 title.標題 + cnt.內文
    
    結構特徵:
    - 每篇文章都有「目標站版」「網址紀錄」「cnt.內文」這 3 個必有欄位
    - 「title.標題」可能在「主文」會出現,但「推文」有時會省略
    
    因此用「目標站版」當分割錨點(每篇必有),確保抓到所有文章。
    """
    with pdfplumber.open(pdf_path) as pdf:
        full_text = ""
        for p in pdf.pages:
            full_text += unicodedata.normalize('NFKC', p.extract_text() or '') + "\n"
    
    # 用「目標站版」當錨點(每篇文章必有)
    station_matches = list(re.finditer(r'目標站版\s+(.+?)(?=\n)', full_text))
    
    posts = []
    最近的標題 = ""  # 同一討論串若無 title.標題 就繼承上一篇的標題(用於分組)
    
    for i, m in enumerate(station_matches):
        # 該篇的範圍:從這個「目標站版」到下一個「目標站版」(或文件結尾)
        start = m.start()
        next_start = station_matches[i + 1].start() if i + 1 < len(station_matches) else len(full_text)
        block = full_text[start:next_start]
        
        # 抓「title.標題」(可能沒有)
        title_match = re.search(r'title\.標題\s+(.+?)(?=\n)', block)
        if title_match:
            title = title_match.group(1).strip().replace('\n', ' ')
            最近的標題 = title  # 更新「最近見過的標題」供後續無標題的篇繼承
        else:
            # 沒有 title.標題 — 用最近見過的標題,加上「#? RE:」前綴標記為衍生回應
            title = f"#? RE: {最近的標題}" if 最近的標題 else "(無標題)"
        
        # 抓「cnt.內文」內容 — 從 cnt.內文 之後直到 Time.發文時間 / 截圖 / 區段結束
        content_match = re.search(r'cnt\.內文(.*?)(?:\n\s*Time\.發文時間|\n\s*截圖|\Z)', block, re.DOTALL)
        content = content_match.group(1).strip() if content_match else ""
        
        posts.append({"title": title, "content": content})
    
    return posts


def normalize_thread_title(title):
    """把標題去掉 #N RE: 前綴 + 過濾 PDF 圖示字符,得到主討論串名稱
    
    例:
    - "[閒聊] 稻草人 不負責任兇手亂猜"        → "[閒聊] 稻草人 不負責任兇手亂猜"
    - "#1 RE: [閒聊] 稻草人 不負責任兇手亂猜"  → "[閒聊] 稻草人 不負責任兇手亂猜"
    - "#? RE: 心目中的反派演員第一名?"        → "心目中的反派演員第一名?"
    - "RE: 心目中的反派演員第一名?"           → "心目中的反派演員第一名?"
    """
    if not title:
        return ""
    cleaned = title
    # 移除 PDF 私用區字符(常是字體圖示,如類型標記、編輯按鈕等)
    cleaned = ''.join(ch for ch in cleaned if not (0xE000 <= ord(ch) <= 0xF8FF))
    cleaned = cleaned.strip()
    # 去除「#XXX RE: 」開頭(XXX 可以是任何非空白字符,例如數字、問號、字母)
    cleaned = re.sub(r'^#\S*\s*RE:\s*', '', cleaned)
    # 去除單純的「RE: 」開頭
    cleaned = re.sub(r'^RE:\s*', '', cleaned)
    # 將內部多重空白統一為單一空白
    cleaned = re.sub(r'\s+', ' ', cleaned)
    return cleaned.strip()


def search_posts(posts, keyword, search_in="content"):
    """依關鍵字搜尋文章
    
    Args:
        posts: extract_posts_with_content() 的回傳
        keyword: 關鍵字,支援:
            - 單一詞: "Friday"
            - 複合 AND: "Friday+稻草人"
            - 複合 OR:  "Friday,稻草人" 或 "Friday|稻草人"
        search_in: 
            - "content": 內文 — 每篇獨立計算
            - "title": 標題 — 同一主討論串視為同一篇
    
    Returns: list of dict, 每筆含 {title, content, snippet_source}
            (title 模式下,同串多篇會合併成一筆,以主文為代表)
    """
    if not keyword.strip():
        return []
    
    kw = keyword.strip()
    
    # 判斷 AND / OR 邏輯
    if '+' in kw:
        parts = [k.strip().lower() for k in kw.split('+') if k.strip()]
        mode = "AND"
    elif ',' in kw or '|' in kw:
        parts = [k.strip().lower() for k in re.split(r'[,|]', kw) if k.strip()]
        mode = "OR"
    else:
        parts = [kw.lower()]
        mode = "AND"
    
    def match(text):
        t = text.lower()
        return all(k in t for k in parts) if mode == "AND" else any(k in t for k in parts)
    
    if search_in == "title":
        # 標題模式:同一主討論串視為同一篇
        # 把同主討論串文章分組,以主文(或第一篇)為代表
        from collections import OrderedDict
        groups = OrderedDict()
        for p in posts:
            key = normalize_thread_title(p["title"])
            if key not in groups:
                groups[key] = []
            groups[key].append(p)
        
        # 對每組:檢查代表標題是否命中(用 normalize 後的主討論串名稱)
        matched = []
        for thread_title, group_posts in groups.items():
            if match(thread_title):
                # 用組內第一篇當代表(通常是主文)
                rep = group_posts[0]
                matched.append({
                    "title": thread_title,
                    "content": rep["content"],
                    "snippet_source": thread_title,  # 標題模式 snippet 來自標題本身
                    "thread_size": len(group_posts),
                })
        return matched
    else:
        # 內文模式:每篇獨立計算
        matched = []
        for p in posts:
            if match(p["content"]):
                matched.append({
                    "title": p["title"],
                    "content": p["content"],
                    "snippet_source": p["content"],
                    "thread_size": 1,
                })
        return matched



    # 文字解析法:更穩健,能避免 pdfplumber 跨頁切錯
    rows = extract_main_table_via_text(pdf_path)
    if rows:
        return rows
    
    # 備援:表格解析(萬一文字解析失效)
    fallback_rows = []
    with pdfplumber.open(pdf_path) as pdf:
        for page in pdf.pages:
            for table in page.extract_tables():
                if not table:
                    continue
                for row in table:
                    if is_main_data_row(row):
                        fallback_rows.append({
                            "站版": normalize(row[0]),
                            "標題": (row[1] or "").strip().replace('\n', ' '),
                            "主軸": normalize(row[2]),
                            "專案發文量": int(row[4]),
                            "網友回應量": int(row[5]),
                            "討論聲量總數": int(row[6]),
                            "正向聲量總數": int(row[7]),
                            "正面討論": int(row[8]),
                            "負面討論": int(row[9]),
                            "議題討論": int(row[10]),
                            "產品討論": int(row[11]),
                            "複合討論": int(row[12]),
                        })
    return fallback_rows


def extract_post_types(pdf_path):
    """抽取「文案類型發文篇數」表格,回傳 dict {類型名: 數量}
    
    用「純文字 + 區段定位」抓取,避免 pdfplumber 跨頁切表導致漏抓。
    """
    with pdfplumber.open(pdf_path) as pdf:
        full_text = ""
        for page in pdf.pages:
            full_text += unicodedata.normalize('NFKC', page.extract_text() or "") + "\n"
    
    types = {}
    
    # 找「文案類型發文篇數」這個區段
    start_idx = full_text.find("文案類型發文篇數")
    if start_idx < 0:
        start_idx = full_text.find("文案類型")
    if start_idx < 0:
        return types
    
    # 區段結尾的關鍵字(碰到就停)
    end_markers = [
        "專案執行進度摘要",
        "操作主軸",
        "專案聲量分佈",
        "網友關注度",
        "網友回應概況",
    ]
    
    # 找最近的結束標記
    end_idx = len(full_text)
    for marker in end_markers:
        idx = full_text.find(marker, start_idx + 10)
        if 0 < idx < end_idx:
            end_idx = idx
    
    section = full_text[start_idx:end_idx]
    
    # 匹配「文案類型名 + 空白 + 純數字」格式的每一行
    for line in section.split('\n'):
        line = line.strip()
        if not line:
            continue
        # 排除標題列
        if line in ("文案類型 累計", "文案類型", "累計"):
            continue
        # 匹配 "<類型名> <數字>" 結構
        m = re.match(r'^(.+?)\s+(\d+)\s*$', line)
        if m:
            name = m.group(1).strip()
            count = int(m.group(2))
            # 排除「合計」
            if name == "合計":
                continue
            # 排除站版分布或含特殊符號的列
            if ":" in name or "%" in name:
                continue
            # 排除含小數點百分比的行
            if re.search(r'\d+\.\d+', line):
                continue
            types[name] = count
    
    return types


# ==================== 計算邏輯 ====================

def categorize_station(stb):
    """把站版名稱對應到模板分類"""
    s = normalize(stb)
    if "PTT" in s.upper():
        return "PTT"
    if "Dcard" in s or "狄卡" in s:
        return "Dcard"
    if "Threads" in s:
        return "Threads"
    if "Facebook" in s or "FB" in s:
        return "FB社團"
    return "其他版面"


def calculate_all(main_data, post_types):
    """計算所有要填入模板的數字"""
    result = {}
    
    # ===== 工作表 1:篇數 =====
    # 模板欄位 → PDF 對應名稱
    # 每種「圖+文」類型涵蓋 4 個變體:素人拍/提供照片 × 過稿/不過稿
    type_mapping = {
        "4~5圖+心得文(素人拍+不過稿)": [
            "4~5圖+心得文(素人拍+不過稿)",
            "4~5圖+心得文(提供照片+不過稿)",
            "4~5圖+心得文(素人拍+過稿)",
            "4~5圖+心得文(提供照片+過稿)",
            "4~5圖+心得文",
        ],
        "2~3圖+分享文(素人拍+過稿)": [
            "2~3圖+分享文(素人拍+過稿)",
            "2~3圖+分享文(提供照片+過稿)",
            "2~3圖+分享文(素人拍+不過稿)",
            "2~3圖+分享文(提供照片+不過稿)",
            "2~3圖+分享文",
        ],
        "1圖+分享文(素人拍+過稿)": [
            "1圖+分享文(素人拍+過稿)",
            "1圖+分享文(提供照片+過稿)",
            "1圖+分享文(素人拍+不過稿)",
            "1圖+分享文(提供照片+不過稿)",
            "1圖+分享文",
        ],
        "分享文": ["分享文"],
        "詳文": ["詳文"],
        "主文": ["主文"],
        "推文": ["推文"],
        "FB-主文": ["FB-主文"],
        "FB-推文": ["FB-推文"],
        "置入主文": ["置入主文"],
        "置入推文": ["置入推文"],
    }
    
    篇數 = {}
    for template_name, pdf_names in type_mapping.items():
        # 累加所有變體的篇數(避免「素人拍+過稿 5 篇 + 素人拍+不過稿 2 篇」只算到 5)
        value = 0
        for pdf_name in pdf_names:
            for k, v in post_types.items():
                if normalize(pdf_name) == normalize(k):
                    value += v
                    break
        篇數[template_name] = value
    result["篇數"] = 篇數
    
    # ===== 工作表 2:KPI =====
    kpi = {}
    # 網友回應數 = 網友回應量整列加總
    kpi["網友回應數"] = sum(r["網友回應量"] for r in main_data)
    # 議題曝光數 = 主軸不含「置入」的列數
    kpi["議題曝光數"] = sum(1 for r in main_data if "置入" not in r["主軸"])
    # 內文指名度 = 跳過(使用者填)
    kpi["內文指名度"] = None
    # 好評增加數 = 各列「正向聲量總數 - 正面討論」先逐列相減再加總
    kpi["好評增加數"] = sum(r["正向聲量總數"] - r["正面討論"] for r in main_data)
    result["KPI"] = kpi
    
    # ===== 工作表 3:網友回應分布 =====
    # 模板順序:PTT、Dcard、Threads、其他版面、FB社團
    分布 = {}
    for cat in ["PTT", "Dcard", "Threads", "其他版面", "FB社團"]:
        items = [r for r in main_data if categorize_station(r["站版"]) == cat]
        分布[cat] = {
            "實際溝通": sum(r["專案發文量"] for r in items),
            "正面討論": sum(r["正面討論"] for r in items),
            "負面討論": sum(r["負面討論"] for r in items),
            "議題討論": sum(r["議題討論"] for r in items),
            "產品討論": sum(r["產品討論"] for r in items),
            "複合討論": sum(r["複合討論"] for r in items),
        }
    result["分布"] = 分布
    result["分布來源"] = {
        cat: [r["站版"] for r in main_data if categorize_station(r["站版"]) == cat]
        for cat in ["PTT", "Dcard", "Threads", "其他版面", "FB社團"]
    }
    
    return result


# ==================== 月報表填充邏輯 ====================

def detect_template_type(wb):
    """偵測模板類型:'monthly' (月報表) 或 'closure' (結案表) 或 'unknown'"""
    sheet_names = wb.sheetnames
    if "網友回應摘要+操作數據" in sheet_names and "版面佔比" in sheet_names:
        return "monthly"
    if "篇數" in sheet_names and "KPI" in sheet_names:
        return "closure"
    return "unknown"


def categorize_station_monthly(stb):
    """月報表的站版分類:PTT / DCARD / THREAD / 其他版面
    
    分類規則(大小寫不敏感):
    - PTT: 站版含 "ptt" 或 "批踢踢"
    - DCARD: 站版含 "dcard" 或 "狄卡"
    - THREAD: 站版含 "thread"(也匹配 Threads/threads/THREADS)
    - 其他版面: 上述以外的所有版面
    """
    s = normalize(stb).lower()  # 全部轉小寫做比對
    if "ptt" in s or "批踢踢" in stb:
        return "PTT"
    if "dcard" in s or "狄卡" in stb:
        return "DCARD"
    if "thread" in s:  # 涵蓋 thread/threads/Thread/Threads/THREADS
        return "THREAD"
    return "其他版面"


def fill_monthly_template(template_path, main_data, post_types):
    """填入月報表模板"""
    wb = load_workbook(template_path)
    
    # ===== 計算 =====
    total_post = sum(r["專案發文量"] for r in main_data)
    total_reply = sum(r["網友回應量"] for r in main_data)
    total_volume = sum(r["討論聲量總數"] for r in main_data)
    sum_pos = sum(r["正面討論"] for r in main_data)
    sum_neg = sum(r["負面討論"] for r in main_data)
    sum_topic = sum(r["議題討論"] for r in main_data)
    sum_prod = sum(r["產品討論"] for r in main_data)
    sum_combo = sum(r["複合討論"] for r in main_data)
    
    # 分母 = 5 類討論加總(等於網友回應量合計)
    denominator = sum_pos + sum_neg + sum_topic + sum_prod + sum_combo
    
    def pct(numerator):
        if denominator == 0:
            return 0.0
        return round(numerator / denominator * 100, 1)
    
    # ----- 頁簽 1:網友回應摘要+操作數據 -----
    ws1 = wb["網友回應摘要+操作數據"]
    
    # C6 = 專案總發文量 + 文案類型明細
    type_detail_parts = []
    for tname, count in post_types.items():
        type_detail_parts.append(f"{tname}{count}")
    if type_detail_parts:
        type_detail_str = "/".join(type_detail_parts)
        ws1["C6"] = f"{total_post}篇\n【{type_detail_str}】"
    else:
        ws1["C6"] = f"{total_post}篇"
    
    ws1["C7"] = f"{total_reply}篇"
    ws1["C8"] = f"{total_volume}篇"
    ws1["C9"] = f"{pct(sum_pos)}% / {sum_pos}篇"
    ws1["C10"] = f"{pct(sum_neg)}% / {sum_neg}篇"
    ws1["C11"] = f"{pct(sum_combo)}% / {sum_combo}篇"
    ws1["C12"] = f"{pct(sum_prod)}% / {sum_prod}篇"
    ws1["C13"] = f"{pct(sum_topic)}% / {sum_topic}篇"
    
    # 5 個討論類型的「篇數=0」整列刪除(從底部往上刪,避免列號錯位)
    discussion_rows = [
        (13, sum_topic),   # 議題
        (12, sum_prod),    # 產品
        (11, sum_combo),   # 複合
        (10, sum_neg),     # 負面
        (9, sum_pos),      # 正面
    ]
    for row_num, count in discussion_rows:
        if count == 0:
            ws1.delete_rows(row_num)
    
    # ----- 頁簽 2:版面佔比 -----
    ws2 = wb["版面佔比"]
    # 模板已有的:B10 PTT / B11 DCARD / B12 THREAD / B13 其他版面
    # 「網友回應數」欄位 = PDF 各站版的「網友回應量」加總
    版面列對應 = [
        ("PTT", 10),
        ("DCARD", 11),
        ("THREAD", 12),
        ("其他版面", 13),
    ]
    cat_reply_sum = {"PTT": 0, "DCARD": 0, "THREAD": 0, "其他版面": 0}
    for r in main_data:
        cat = categorize_station_monthly(r["站版"])
        cat_reply_sum[cat] += r["網友回應量"]
    
    # 先填值
    for cat, row in 版面列對應:
        ws2.cell(row=row, column=3).value = cat_reply_sum[cat]
    
    # 找出要刪的列(網友回應量=0 的版面)
    要刪除列號 = [row for cat, row in 版面列對應 if cat_reply_sum[cat] == 0]
    
    # 從底部往上刪(避免列號錯位)
    for row_num in reversed(要刪除列號):
        ws2.delete_rows(row_num)
    
    # 重新計算剩下的資料範圍(用來更新圓餅圖)
    保留版面數 = 4 - len(要刪除列號)
    if 保留版面數 > 0:
        新資料結束列 = 10 + 保留版面數 - 1  # 例如保留 3 個版面 → 列 10-12
        
        # 更新圓餅圖的資料範圍
        from openpyxl.chart.reference import Reference
        for chart in ws2._charts:
            # 用新的 Reference 重建類別軸與數值
            cat_ref = Reference(ws2, min_col=2, min_row=10, max_col=2, max_row=新資料結束列)
            val_ref = Reference(ws2, min_col=3, min_row=10, max_col=3, max_row=新資料結束列)
            # 清空舊 series,加新的
            chart.series = []
            chart.add_data(val_ref, titles_from_data=False)
            chart.set_categories(cat_ref)
    
    # ----- 頁簽 3「總覽整理」:不處理 -----
    
    output = BytesIO()
    wb.save(output)
    return output.getvalue()


def fill_template(template_path, calc_result):
    """把計算結果填入模板,回傳填好的 xlsx bytes"""
    wb = load_workbook(template_path)
    
    # ----- 工作表 1:篇數 -----
    ws1 = wb["篇數"]
    from copy import copy
    
    篇數資料 = calc_result["篇數"]
    
    # === 檢查 PDF 是否含「4~5圖+心得文」變體(且實際篇數 > 0)===
    四五圖類型 = [k for k in 篇數資料.keys() if "4~5圖" in k and 篇數資料.get(k, 0) > 0]
    要插入4_5圖 = len(四五圖類型) > 0
    四五圖總篇數 = sum(篇數資料.get(k, 0) for k in 四五圖類型) if 要插入4_5圖 else 0
    四五圖代表名 = 四五圖類型[0] if 要插入4_5圖 else None
    
    # 文案類型欄位順序(從左到右)
    # 沒有 4~5圖時:2~3圖、1圖、分享文、詳文、主文、推文、FB-主文、FB-推文、置入主文、置入推文(10 欄)
    # 有 4~5圖時 :4~5圖、2~3圖、1圖、分享文、詳文、主文、推文、FB-主文、FB-推文、置入主文、置入推文(11 欄)
    
    if 要插入4_5圖:
        # === 動態插入 4~5圖 欄/列 ===
        # 1. 上方小表 A 的合併儲存格(C5:L5)會被 insert_cols 影響,先解除再重建
        舊合併 = None
        for rng in list(ws1.merged_cells.ranges):
            if rng.min_row == 5 and rng.max_row == 5 and rng.min_col == 3:
                舊合併 = (rng.min_col, rng.max_col)
                ws1.unmerge_cells(str(rng))
                break
        
        # 2. 在 C 欄之前插入新欄(會影響到上方小表 A 跟 B,因為它們都用 C-L 欄)
        ws1.insert_cols(3)
        # 此時:
        #   原 C(2~3圖)→ 變成 D
        #   原 L(置入推文)→ 變成 M
        #   新 C 是空白欄
        
        # 3. 在 C 欄寫入 4~5圖 的內容
        # 上方小表 A:列 3 表頭、列 4 篇數
        ws1["C3"] = "4~5圖\n心得文"
        ws1["C4"] = 四五圖總篇數
        # 上方小表 B:列 7 完整名稱、列 8 篇數
        ws1["C7"] = 四五圖代表名
        ws1["C8"] = 四五圖總篇數
        # 套用樣式(複製 D 欄相對應位置的格式)
        for src_row in [3, 4, 7, 8]:
            src_cell = ws1.cell(row=src_row, column=4)  # D 欄
            new_cell = ws1.cell(row=src_row, column=3)  # 新 C 欄
            new_cell.fill = copy(src_cell.fill)
            new_cell.font = copy(src_cell.font)
            new_cell.alignment = copy(src_cell.alignment)
            new_cell.border = copy(src_cell.border)
        # 列 5 (總計列)也要套樣式 — 從 D5(原 C5,有灰底)複製
        d5 = ws1.cell(row=5, column=4)
        c5 = ws1.cell(row=5, column=3)
        c5.fill = copy(d5.fill)
        c5.font = copy(d5.font)
        c5.border = copy(d5.border)
        
        # 4. 重新合併總計列(範圍從 C5:L5 → C5:M5)
        if 舊合併:
            from openpyxl.utils import get_column_letter
            ws1.merge_cells(f"C5:{get_column_letter(舊合併[1] + 1)}5")
        
        # 5. 下方清單 C:在列 15 之前插入新列
        ws1.insert_rows(15)
        ws1["B15"] = 四五圖代表名
        ws1["C15"] = 四五圖總篇數
        # 套用 B16/C16 的樣式
        for col_letter in ["B", "C"]:
            src = ws1[f"{col_letter}16"]
            dst = ws1[f"{col_letter}15"]
            dst.fill = copy(src.fill)
            dst.font = copy(src.font)
            dst.alignment = copy(src.alignment)
            dst.border = copy(src.border)
        
        # 6. 調整映射表(因插入了 1 欄 + 1 列)
        # 上方小表 B 是列 7-8(欄向後位移 1)
        篇數欄位映射 = {
            "2~3圖+分享文(素人拍+過稿)": "D8",
            "1圖+分享文(素人拍+過稿)": "E8",
            "分享文": "F8",
            "詳文": "G8",
            "主文": "H8",
            "推文": "I8",
            "FB-主文": "J8",
            "FB-推文": "K8",
            "置入主文": "L8",
            "置入推文": "M8",
        }
        # 上方小表 A 列 4 篇數(欄向後位移 1)
        上方小表映射 = {
            "2~3圖+分享文(素人拍+過稿)": "D4",
            "1圖+分享文(素人拍+過稿)": "E4",
            "分享文": "F4",
            "詳文": "G4",
            "主文": "H4",
            "推文": "I4",
            "FB-主文": "J4",
            "FB-推文": "K4",
            "置入主文": "L4",
            "置入推文": "M4",
        }
        # 下方清單 C(列向後位移 1,因為插入了列 15)
        區塊B映射 = {
            "2~3圖+分享文(素人拍+過稿)": "C16",
            "1圖+分享文(素人拍+過稿)": "C17",
            "分享文": "C18",
            "詳文": "C19",
            "主文": "C20",
            "推文": "C21",
            "FB-主文": "C22",
            "FB-推文": "C23",
            "置入主文": "C24",
            "置入推文": "C25",
        }
        合計列號 = 26  # 原本 25 + 1
        上方小表最大欄 = 13  # M(原本 L=12 + 1)
    else:
        # === 原本邏輯:沒有 4~5圖 時 ===
        篇數欄位映射 = {
            "2~3圖+分享文(素人拍+過稿)": "C8",
            "1圖+分享文(素人拍+過稿)": "D8",
            "分享文": "E8",
            "詳文": "F8",
            "主文": "G8",
            "推文": "H8",
            "FB-主文": "I8",
            "FB-推文": "J8",
            "置入主文": "K8",
            "置入推文": "L8",
        }
        上方小表映射 = {
            "2~3圖+分享文(素人拍+過稿)": "C4",
            "1圖+分享文(素人拍+過稿)": "D4",
            "分享文": "E4",
            "詳文": "F4",
            "主文": "G4",
            "推文": "H4",
            "FB-主文": "I4",
            "FB-推文": "J4",
            "置入主文": "K4",
            "置入推文": "L4",
        }
        區塊B映射 = {
            "2~3圖+分享文(素人拍+過稿)": "C15",
            "1圖+分享文(素人拍+過稿)": "C16",
            "分享文": "C17",
            "詳文": "C18",
            "主文": "C19",
            "推文": "C20",
            "FB-主文": "C21",
            "FB-推文": "C22",
            "置入主文": "C23",
            "置入推文": "C24",
        }
        合計列號 = 25
        上方小表最大欄 = 12  # L
    
    # === 填值到上方小表 B(列 7-8)===
    for name, cell in 篇數欄位映射.items():
        ws1[cell] = 篇數資料.get(name, 0)
    
    # === 填值到上方小表 A 第 4 列「篇數」+ 區塊 B 下方清單 + 第 5 列「總計」===
    for name, cell in 上方小表映射.items():
        ws1[cell] = 篇數資料.get(name, 0)
    
    # 上方小表 A 第 5 列「總計」
    上方小表總計 = sum(篇數資料.get(name, 0) for name in 上方小表映射.keys())
    if 要插入4_5圖:
        上方小表總計 += 四五圖總篇數
    
    # === 處理上方小表 A 第 5 列(合併儲存格)+ 刪除 0 欄 ===
    # (1) 找出合併範圍 + 保存 C5 樣式 + 解除合併
    上方小表_merged = None
    保留_C5樣式 = None
    for rng in list(ws1.merged_cells.ranges):
        if rng.min_row == 5 and rng.max_row == 5 and rng.min_col == 3:
            上方小表_merged = (rng.min_col, rng.max_col)
            c5_cell = ws1.cell(row=5, column=3)
            保留_C5樣式 = {
                "fill": copy(c5_cell.fill),
                "font": copy(c5_cell.font),
                "border": copy(c5_cell.border),
            }
            ws1.unmerge_cells(str(rng))
            break
    
    # (2) 把整個原合併範圍的填色設成 C5 樣式(灰底),確保刪欄後仍是灰底
    if 上方小表_merged and 保留_C5樣式:
        for col in range(上方小表_merged[0], 上方小表_merged[1] + 1):
            cell = ws1.cell(row=5, column=col)
            cell.fill = 保留_C5樣式["fill"]
            cell.font = 保留_C5樣式["font"]
            cell.border = 保留_C5樣式["border"]
    
    # (3) 從右到左刪除「篇數=0」的欄(範圍是 C-最大欄)
    刪除欄數 = 0
    for col_idx in range(上方小表最大欄, 2, -1):
        篇數值 = ws1.cell(row=4, column=col_idx).value
        if 篇數值 == 0:
            ws1.delete_cols(col_idx)
            刪除欄數 += 1
    
    # (4) 重新合併剩下的範圍 + 寫入總計值
    if 上方小表_merged is not None and 刪除欄數 < (上方小表_merged[1] - 上方小表_merged[0] + 1):
        新最右欄 = 上方小表_merged[1] - 刪除欄數
        from openpyxl.utils import get_column_letter
        from openpyxl.styles import Alignment
        if 新最右欄 > 上方小表_merged[0]:
            合併範圍 = f"{get_column_letter(上方小表_merged[0])}5:{get_column_letter(新最右欄)}5"
            ws1.merge_cells(合併範圍)
        總計儲存格 = ws1.cell(row=5, column=上方小表_merged[0])
        總計儲存格.value = 上方小表總計
        總計儲存格.alignment = Alignment(horizontal="center", vertical="center")
    
    # === 區塊 B (下方清單) 填值 + 合計 + 刪 0 列 ===
    for name, cell in 區塊B映射.items():
        ws1[cell] = 篇數資料.get(name, 0)
    
    # 合計列(隨 4~5圖 插入而動,在 合計列號)
    區塊B總計 = sum(篇數資料.get(name, 0) for name in 區塊B映射.keys())
    if 要插入4_5圖:
        區塊B總計 += 四五圖總篇數
    ws1.cell(row=合計列號, column=3).value = 區塊B總計
    
    # 刪除「篇數=0」的列(從下到上,避免列號錯位)
    區塊B_列範圍 = list(區塊B映射.items())
    for name, cell in reversed(區塊B_列範圍):
        row_num = int(cell[1:])
        if 篇數資料.get(name, 0) == 0:
            ws1.delete_rows(row_num)
    
    # ----- 工作表 2:KPI -----
    ws2 = wb["KPI"]
    ws2["D4"] = f"{calc_result['KPI']['網友回應數']}篇"
    ws2["D5"] = f"{calc_result['KPI']['議題曝光數']}串"
    # D6 內文指名度 - 跳過(留原值或清空)
    ws2["D6"] = ""  # 清空,讓使用者自己填
    ws2["D7"] = f"{calc_result['KPI']['好評增加數']}篇"
    
    # ----- 工作表 3:網友回應分布 -----
    ws3 = wb["網友回應分布"]
    # 列對應(已知模板:PTT=5列, Dcard=6列, Threads=7列, 其他=8列, FB=9列)
    版面列對應 = [
        ("PTT", 5),
        ("Dcard", 6),
        ("Threads", 7),
        ("其他版面", 8),
        ("FB社團", 9),
    ]
    
    # 先判斷哪些版面要刪除(整列全為 0)
    要刪除的版面 = set()
    for cat, _ in 版面列對應:
        d = calc_result["分布"][cat]
        if (d["實際溝通"] == 0 and d["正面討論"] == 0 and d["負面討論"] == 0
                and d["議題討論"] == 0 and d["產品討論"] == 0 and d["複合討論"] == 0):
            要刪除的版面.add(cat)
    
    # 從底部往上刪除(避免列號錯位)
    for cat, row_num in reversed(版面列對應):
        if cat in 要刪除的版面:
            ws3.delete_rows(row_num)
    
    # 刪除後重新計算保留版面的新列號(按原順序)
    保留版面 = [(cat, orig_row) for cat, orig_row in 版面列對應 if cat not in 要刪除的版面]
    
    # 重新填值到新位置:從列 5 開始連續排列
    for new_idx, (cat, _) in enumerate(保留版面):
        row_num = 5 + new_idx
        d = calc_result["分布"][cat]
        ws3.cell(row=row_num, column=3).value = d["實際溝通"]   # C
        ws3.cell(row=row_num, column=4).value = d["正面討論"]   # D
        ws3.cell(row=row_num, column=5).value = d["負面討論"]   # E
        ws3.cell(row=row_num, column=6).value = d["議題討論"]   # F
        ws3.cell(row=row_num, column=7).value = d["產品討論"]   # G
        ws3.cell(row=row_num, column=8).value = d["複合討論"]   # H
        # I 欄(回應小計)— 直接寫入計算好的數值,不用公式
        回應小計 = d["正面討論"] + d["負面討論"] + d["議題討論"] + d["產品討論"] + d["複合討論"]
        ws3.cell(row=row_num, column=9).value = 回應小計
    
    # 修正底部「發文篇數總計」列的公式範圍
    # 原模板總計在第 14 列(列 5-9 是版面、10-13 是空白、14 是總計)
    # 1. 先刪除空白列 10-13(模板殘留的舊公式列)
    # 2. 刪了 N 列(空版面)+ 4 列空白 後總計列變成 14-刪除版面數-4
    刪除數 = len(要刪除的版面)
    
    # 刪除模板殘留的「空白計算列」10、11、12、13
    新總計列原始 = 14 - 刪除數
    for offset in range(1, 5):
        ws3.delete_rows(新總計列原始 - offset)
    
    # 計算總計列的位置 + 直接寫入數值(不用公式,避免 Excel 不自動算)
    總計列 = 14 - 刪除數 - 4
    # 直接算出總和填入
    分布總和 = {"實際溝通": 0, "正面討論": 0, "負面討論": 0, "議題討論": 0, "產品討論": 0, "複合討論": 0}
    for cat, _ in 保留版面:
        d = calc_result["分布"][cat]
        for k in 分布總和:
            分布總和[k] += d[k]
    
    ws3.cell(row=總計列, column=3).value = 分布總和["實際溝通"]   # C
    ws3.cell(row=總計列, column=4).value = 分布總和["正面討論"]   # D
    ws3.cell(row=總計列, column=5).value = 分布總和["負面討論"]   # E
    ws3.cell(row=總計列, column=6).value = 分布總和["議題討論"]   # F
    ws3.cell(row=總計列, column=7).value = 分布總和["產品討論"]   # G
    ws3.cell(row=總計列, column=8).value = 分布總和["複合討論"]   # H
    # I 欄回應小計
    ws3.cell(row=總計列, column=9).value = (
        分布總和["正面討論"] + 分布總和["負面討論"] + 分布總和["議題討論"]
        + 分布總和["產品討論"] + 分布總和["複合討論"]
    )
    
    # 輸出到 bytes
    output = BytesIO()
    wb.save(output)
    return output.getvalue()


def convert_xls_to_xlsx(xls_bytes):
    """把 .xls 轉成 .xlsx (因為 openpyxl 無法處理舊版 .xls)"""
    with tempfile.TemporaryDirectory() as tmpdir:
        in_path = os.path.join(tmpdir, "input.xls")
        with open(in_path, "wb") as f:
            f.write(xls_bytes)
        
        result = subprocess.run(
            ['libreoffice', '--headless', '--convert-to', 'xlsx', '--outdir', tmpdir, in_path],
            capture_output=True, text=True, timeout=120
        )
        if result.returncode != 0:
            raise RuntimeError(f"LibreOffice 轉檔失敗: {result.stderr}")
        
        out_path = os.path.join(tmpdir, "input.xlsx")
        if not os.path.exists(out_path):
            raise RuntimeError("LibreOffice 沒有產生 xlsx 檔")
        
        with open(out_path, "rb") as f:
            return f.read()


